window.NPC_CHUNK_23 = [{"name":"Ilivorr Karanasi","cr":20,"xp":307200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"witch","level":20}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":9,"senses":["see invisibility"],"ac":32,"ac_touch":22,"ac_flat_footed":26,"ac_mods":"+5 armor, +5 deflection, +5 Dex, +1 dodge, +1 insight, +5 natural","hp":185,"hd":"20d6+95","hd_value":20,"fort":17,"ref":20,"will":24,"dr":"10/adamantine","immunities":["fear"],"resists":["cold 20"],"sr":18,"speed":[{"type":"fly","speed":120},{"type":"land","speed":60}],"melee":"+2 wounding kukri +21 (1d4+4/15-20 plus 1 bleed), +1 shocking burst kukri +20 (1d4+2/15-20 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"agony, blight, evil eye, death curse, flight, forced reincarnation, healing, major healing, misfortune, retribution, slumber"}],"spellsprepared_caster_level":20,"spellsprepared_concentration":26,"spellsprepared":[{"spell_level":9,"spell_slots":4,"spells":[{"spell":"mass hold monster"},{"spell":"maximized cone of cold"},{"spell":"power word kill"},{"spell":"wail of the banshee"}]},{"spell_level":8,"spell_slots":4,"spells":[{"spell":"fire storm"},{"spell":"horrid wilting"},{"spell":"power word stun"},{"spell":"quickened cure serious wounds"}]},{"spell_level":7,"spell_slots":4,"spells":[{"spell":"chain lightning","count":2},{"spell":"heal"},{"spell":"power word blind"}]},{"spell_level":6,"spell_slots":5,"spells":[{"spell":"flesh to stone"},{"spell":"greater heroism"},{"spell":"maximized lightning bolt","count":2},{"spell":"slay living"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"baleful polymorph"},{"spell":"feeblemind"},{"spell":"flame strike"},{"spell":"maximized cure moderate wounds"},{"spell":"waves of fatigue"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"black tentacles"},{"spell":"dimension door"},{"spell":"ice storm"},{"spell":"maximized shocking grasp"},{"spell":"wall of ice"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"dispel magic","count":2},{"spell":"lightning bolt","count":2}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blindness/deafness"},{"spell":"cure moderate wounds","count":2},{"spell":"death knell"},{"spell":"false life"},{"spell":"spectral hand"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"inflict light wounds"},{"spell":"obscuring mist"},{"spell":"ray of enfeeblement"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":4,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"touch of fatigue (DC 16) Patron elements"}]}],"strength":14,"dexterity":20,"constitution":16,"intelligence":22,"wisdom":18,"charisma":14,"baseatk":10,"cmb":20,"cmd":34,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Improved Critical (kukri)"},{"feat":"Improved Initiative"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Martial Weapon Proficiency"},{"feat":"Maximize Spell"},{"feat":"Quicken Spell"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (kukri)"}],"skills":[{"skill":"Craft (alchemy)","value":33},{"skill":"Fly","value":32},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (history)","value":28},{"skill":"Knowledge (nature)","value":28},{"skill":"Knowledge (planes)","value":28},{"skill":"Perception","value":32},{"skill":"Sense Motive","value":10},{"skill":"Spellcraft","value":33},{"skill":"Use Magic Device","value":29}],"languages":["Common","Aklo","Draconic","Giant","Hallit","Infernal","Skald"],"sq":["enhanced NPC","witch's familiar (raven named Cain)"],"special_abilities":[{"type":"Agony","kind":"Su","details":": Can affect one creature within 60 feet, causing it to be nauseated (Fort DC 26 negates) for 20 rounds. A new save is allowed each round. A creature can only be affected once per day."},{"type":"Blight","kind":"Su","details":": Cause the following curse against an Animal or Plant creature with 1 round of contact. Blight Hex: type curse; save Will DC 26 negates; frequency 1/day; effect 1 Con damage. Remove curse DC 26. Only one blight hex can be active at a time."},{"type":"Death Curse","kind":"Su","details":": Cause a creature within 30 ft. to become fatigued on the first round and exhausted on the second round. On the third round, the creature must make a DC 26 Fortitude save or die. A DC 26 Will save on the first round negates the entire effect. Creatures that fail the first save but succeed at the second remain exhausted and take 4d6+20 points of damage. Killing Ilivorr ends the hex, but any fatigue or exhaustion remains. A creature can only be affected once per day."},{"type":"Enhanced NPC","details":"Ilivorr's stats are built using a 20-point buy, and she has twice as much gear as is normal for an NPC of her level. These advantages increase her total CR by +1. Hexes Using a hex is a standard action that doesn't provoke an attack of opportunity. The following hexes are summarized from the Pathfinder RPG Advanced Player's Guide, pages 66-69."},{"type":"Evil Eye","kind":"Su","details":": Cause a foe within 30 ft. to take a -4 penalty on one of the following (Ilivorr's choice) for 9 rounds: AC, ability checks, attack rolls, saving throws, or skill checks. A DC 26 Will save reduces the duration to 1 round. This is a mind-affecting effect."},{"type":"Flight","kind":"Su","details":": Feather fall at will, +4 racial bonus on Swim checks, levitate 1/day, and fly 20 minutes/day in 1-minute increments."},{"type":"Forced Reincarnation","kind":"Su","details":": Cause a creature within 30 ft. to die and be immediately reincarnated into a new body (Will DC 26 negates). A creature can only be affected once per day."},{"type":"Healing","kind":"Su","details":": Cure moderate wounds (CL 20th) once per creature per day."},{"type":"Major Healing","kind":"Su","details":": Cure critical wounds (CL 20th) once per creature per day."},{"type":"Misfortune","kind":"Su","details":": Cause a creature within 30 ft. to roll twice and take the worst result on any ability check, attack roll, saving throw, or skill check for 3 rounds (Will DC 26 negates). A creature can only be affected once per day."},{"type":"Retribution","kind":"Su","details":": Cause a creature within 60 ft. to take damage when it attacks for 6 rounds (Will DC 26 negates). Whenever that creature deals damage in melee, it immediately takes half that damage (round down). This damage bypasses any resistances, immunities, or damage resistance."},{"type":"Slumber","kind":"Su","details":": Cause a creature of any HD within 30 ft. to fall asleep, as the sleep spell (Will DC 26 negates). The hex ends immediately if the creature takes damage. A creature can only be affected once per day."},{"type":"Witch's Familiar","kind":"Ex","details":"A witch forms a close bond with a familiar, a creature that teaches her magic and helps to guide her along her path. Instead of a spellbook, Ilivorr must commune with her familiar each day to prepare her spells. A witch's familiar otherwise functions like the wizard's arcane bond class feature."}],"gear":"+2 wounding kukri, +1 shocking burst kukri, belt of physical perfection +4, boots of speed, hand of glory, headband of mental prowess +4 (Intelligence and Wisdom), dusty rose prism ioun stone, major ring of cold resistance, ring of protection +5, black robe of the archmagi, potion of barkskin (CL 12th), ring of the ram (35 charges), stone salve, wand of vampiric touch (CL 20th, 21 charges)","before_combat":"Ilivorr casts false life on herself each day. In preparation for the arrival of the PCs in the cenotaph, she uses her flight hex, drinks her potion of barkskin, uses her stone salve, and activates her boots of speed. She casts greater heroism, spectral hand, and see invisibility from her hand of glory. Ilivorr then casts grease directly in front of the clock portal and readies an action to release 3 charges from her ring of the ram at the doughtiest fighter.","during_combat":"Ilivorr uses her flight hex to stay airborne away from the PCs. She casts spells that can affect multiple foes, such as mass hold monster, wail of the banshee, chain lightning, or black tentacles. She targets a spellcaster with feeblemind or her agony hex, and uses her death curse, forced reincarnation, and retribution hexes on anyone who closes to fight in melee. She uses her spectral hand to deliver vampiric touches from her wand.","morale":"Ilivorr defends the cenotaph and its contents to the death.","base_statistics":"Without her spells, Ilivorr has the following statistics: AC 26, touch 21, flat-footed 21; hp 150; Fort +13, Ref +15, Will +20; Speed 30 ft.; Melee +2 wounding kukri +16/+11 (1d4+4/15-20 plus 1 bleed), +1 shocking burst kukri +15/+10 (1d4+2/15-20 plus 1d6 electricity); CMB +15; CMD 33","source":"The Witchwar Legacy, Pathfinder RPG Advanced Player's Guide 65"},{"name":"Nareem Daress","cr":7,"xp":3200,"race":"half-Orc","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":3},{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human","incorporeal","orc"],"templates_applied":"ghost","init":7,"senses":["darkvision 60 ft."],"auras":["ghostly swarm (10 ft.)"],"ac":17,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+4 deflection, +3 Dex","hp":63,"hd":"3d10+3d8+33","hd_value":6,"fort":8,"ref":9,"will":5,"defensive_abilities":["channel resistance +4","evasion","incorporeal","rejuvenation","trap sense +1"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +8 (7d6, Fort. DC 17 half)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humans +2"},{"type":"sneak attack","details":"+2d6"}],"dexterity":17,"intelligence":10,"wisdom":12,"charisma":18,"baseatk":5,"cmb":8,"cmd":22,"feats":[{"feat":"Endurance"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Toughness"},{"feat":"Two-Weapon Fighting"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Appraise","value":8},{"skill":"Climb","value":8},{"skill":"Disable Device","value":8},{"skill":"Fly","value":11},{"skill":"Knowledge (geography)","value":8},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":18},{"skill":"Stealth","value":20},{"skill":"Survival","value":10}],"languages":["Common","Orc"],"sq":["favored terrain (jungle +2)","rogue talents (surprise attack)","track +1","trapfinding +1","wild empathy +7"],"special_abilities":[{"type":"Ghostly Swarm","kind":"Su","details":"Nareem was devoured by army ants, and their ghostly bodies still crawl over and around him. These incorporeal ants swarm over any living creature within 10 ft. of Nareem. Affected creatures take 3d6 points of damage per round and are nauseated for as long as they remain within the aura (a DC 17 Fortitude save halves the damage and negates the nausea)."}],"during_combat":"Nareem doesn't immediately manifest when intruders arrive, but he takes note of them from hiding within the stones of the ruined building. If the intruders make no sign of leaving after a minute, he moves to attack, eager to drive them off from the city he still feels is rightfully his discovery. When he attacks, the first things that manifests are the ghostly ants of his swarm-these army ants appear to crawl out of the walls and ground in swiftly increasing numbers. Nareem himself remains inside of the solid stone or ground for 1 round; if the manifestation of his swarm doesn't scare off the intruders, he emerges to attack. Nareem focuses his attacks on anyone who is obviously (or likely to be) a Pathfinder, shrieking phrases like, \"It's mine! I found it! The city is mine!\" while he tries to kill (or at least run off) the intruders.","morale":"Nareem fights until destroyed, rejuvenating in 2d4 days. During this period of rejuvenation, solitary ghostly ants can be seen crawling around on the ruins or the ground. Nareem can be laid to rest permanently only by ensuring that the discovery of Saventh-Yhi is credited to him in a printed copy of the Pathfinder Chronicles. It's possible for a deceptive character to trick Nareem into accepting a forgery or illusory Pathfinder Chronicle as the real thing and thus put him to rest-doing so requires either a successful opposed Linguistics check (for an actual forgery) or a failed Will save on Nareem's part (for an illusion).","source":"AP 39, Pathfinder RPG Bestiary 144"},{"name":"Yog'oltha","cr":11,"xp":12800,"race":"aboleth","age_category":"Adult","alignment":"LE","size":"Huge","type":"aberration","sub_types":["aquatic"],"templates_applied":"advanced","init":5,"senses":["darkvision 60 ft."],"auras":["mucus cloud (5 ft., Fort. DC 23)"],"ac":25,"ac_touch":10,"ac_flat_footed":24,"ac_mods":"+1 deflection, +1 Dex, +13 natural, +2 shield, -2 size","hp":147,"hd":"14d8+84","hd_value":14,"fort":10,"ref":7,"will":14,"speed":[{"type":"land","speed":10},{"type":"swim","speed":60}],"melee":"4 tentacles +14 (1d8+5 plus slime [Fort. DC 23])","space":"15 ft.","reach":"15 ft.","spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"hypnotic pattern"},{"spell":"illusory wall"},{"spell":"mirage arcana"},{"spell":"persistent image"},{"spell":"programmed image"},{"spell":"project image"},{"spell":"veil"}]},{"frequency":"3/day","spells":[{"spell":"dominate monster"}]}],"strength":20,"dexterity":12,"constitution":22,"intelligence":15,"wisdom":17,"charisma":18,"baseatk":10,"cmb":17,"cmd":29,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Lightning Reflexes"},{"feat":"Improved Natural Armor"},{"feat":"Improved Natural Attack (tentacle)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Bluff","value":18},{"skill":"Intimidate","value":21},{"skill":"Knowledge (history)","value":19},{"skill":"Linguistics","value":4},{"skill":"Perception","value":20},{"skill":"Spellcraft","value":19},{"skill":"Survival","value":10},{"skill":"Swim","value":24}],"languages":["Aboleth","Aklo","Aquan","Azlanti","Polyglot","Undercommon"],"gear":"amulet of natural armor +1, ring of force shield, ring of protection +1","during_combat":"Yog'oltha uses veil to mask its actual appearance, taking the illusory form of a serpentfolk wizard before it initiates combat with the PCs via a projected image from behind an illusory wall. The aboleth uses dominate monster to try to control the most heavily armored PCs, ordering them to attack their allies (this use allows a second saving throw to throw off the effects). The aboleth then uses other illusions to try to trick the PCs into using valuable resources fighting against fantasies. If the PCs see through the ruse, the aboleth attacks physically, focusing its wrath on obvious divine spellcasters first.","morale":"If reduced below 40 hit points, Yog'oltha flees into the depths of the central lake, using illusions to cover its retreat and, upon finally reaching a hiding place, placing an illusory wall to hide behind. It lingers in hiding until it is healed, then ventures out to dominate new targets to use them against the PCs in an attempt to kill them from afar. If directly confronted and reduced to 40 or fewer hit points a second time, it flees again but doesn't attempt further vengeance. In time, Yog'oltha may seek a way to escape Saventh-Yhi and return to the sea.","source":"AP 39, Pathfinder RPG Bestiary 8"},{"name":"Charau-ka Thug","cr":4,"xp":1200,"race":"Charau-ka","age_category":"Adult","classes":[{"class":"warrior","level":3}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["charau-ka"],"init":1,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":18,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+3 armor, +1 Dex, +2 natural, +1 shield, +1 size","hp":44,"hd":"3d8+3d10+15","hd_value":6,"fort":6,"ref":5,"will":3,"speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"mwk darkwood club +10 (1d4+2), bite +3 (1d3+1)","ranged":"mwk throwing axe +9 (1d4+2/19-20)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":13,"constitution":14,"intelligence":8,"wisdom":12,"charisma":11,"baseatk":5,"cmb":6,"cmd":17,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Throw Anything","type":"bonus"},{"feat":"Weapon Focus (club)"}],"skills":[{"skill":"Climb","value":14},{"skill":"Intimidate","value":6},{"skill":"Perception","value":2},{"skill":"Stealth","value":10}],"languages":["Abyssal","Polyglot"],"special_abilities":[{"type":"Shrieking Frenzy","kind":"Su","details":"Once per day, a charau-ka can enter a state of shrieking frenzy as a free action. While in this state, the charau-ka automatically fails Stealth checks and cannot speak or cast spells that use verbal components (or use items that require command words to activate), but functions as if under the effects of a haste spell. A charau-ka can continue shrieking for up to 3 rounds, after which it is staggered for 1 round."},{"type":"Thrown Weapon Mastery","kind":"Ex","details":"Charau-ka are masters of thrown weapons. All charau-ka gain Throw Anything as a bonus feat. In addition, a charau-ka gains a +1 racial bonus on all thrown weapons, and the threat range for thrown weapons is doubled, as if the charau-ka possessed the Improved Critical feat for all thrown weapons. This effect doesn't stack with any other effect that expands the threat range of a weapon."}],"gear":"masterwork studded leather, masterwork darkwood light wooden shield, masterwork darkwood club, masterwork throwing axes (2), potion of cure moderate wounds","during_combat":"A charau-ka thug enters a shrieking frenzy on the first round of combat. If it's injured when the frenzy ends, it drinks its potion of cure moderate wounds before continuing the fight.","morale":"Unless it's in the presence of one of the tribe's leaders, a charau-ka thug flees combat or surrenders if reduced to fewer than 10 hit points.","source":"AP 39, World Guide: The Inner Sea 308"},{"name":"Olujimi","cr":9,"xp":6400,"race":"angazhani","gender":"Male","age_category":"Adult","alignment":"CE","size":"Large","type":"magical beast","init":3,"senses":["darkvision 60 ft.","low-light vision","scent","see invisibility"],"ac":24,"ac_touch":12,"ac_flat_footed":21,"ac_mods":"+2 armor, +3 Dex, +8 natural, +2 shield, -1 size","hp":114,"hd":"12d10+48","hd_value":12,"fort":12,"ref":11,"will":8,"dr":"10/cold iron or good","immunities":["electricity","poison"],"resists":["acid 10","cold 10","fire 10"],"sr":20,"speed":[{"type":"climb","speed":40},{"type":"land","speed":40}],"melee":"+1 throwing axe +16 (1d8+6), 2 mwk throwing axes +16 (1d8+5), bite +11 (1d8+2) or bite +16 (1d8+5), 3 claws +16 (1d6+5)","ranged":"+1 throwing axe +16 (1d8+6), 2 mwk throwing axes +16 (1d8+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"4 claws +16, 1d6+7"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"dimension door"},{"spell":"dispel magic"}]},{"frequency":"3/day","spells":[{"spell":"dominate monster"},{"spell":"fear"}]}],"strength":21,"dexterity":17,"constitution":18,"intelligence":12,"wisdom":14,"charisma":15,"baseatk":12,"cmb":18,"cmd":31,"feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Multiweapon Fighting"},{"feat":"Power Attack"},{"feat":"Weapon Focus (throwing axe)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Intimidate","value":8},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":11},{"skill":"Stealth","value":8},{"skill":"Survival","value":8}],"languages":["Common","Abyssal","Polyglot"],"sq":["martial training"],"special_abilities":[{"type":"Martial Training","kind":"Ex","details":"Because of their high intelligence, angazhani are proficient with light and medium armors, simple weapons, and one martial weapon of choice."}],"gear":"+1 light wooden shield, +1 throwing axe, masterwork throwing axes (7), bracers of armor +2, leather axe harness","during_combat":"Olujimi starts combat by throwing his nonmagical throwing axes at different targets, then roars in to attack other foes with his magic axe and claws. If he drops a foe to negative hit points, his bloodlust gets the better of him and he abandons both shield and weapon to fight the rest of the battle with his claws, eager to finish the fight with some rending ruin. He saves fear and dominate monster to use against any spellcasters who seem to be particularly troublesome or against foes he can't engage in melee. If he dominates a foe, he orders that foe to cast aside his weapons, drop to his knees, and pay homage to him.","morale":"Olujimi uses dimension door to escape if brought below 40 hit points, seeking out Akkituk and ordering her to use stone salve on the statue of the ape demon. He attempts to use dominate monster on the ape demon to send it against the PCs, but if that fails, he tries to lure the monster back so that the PCs need to fight it anyway. When he reenters combat with the PCs, Olujimi fights to the death.","source":"AP 39, Heart of the Jungle 58"},{"name":"Akkituk","cr":8,"xp":4800,"race":"charau-ka","gender":"Female","age_category":"venerable","classes":[{"class":"cleric of Angazhan","level":7}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["charau-ka"],"init":-1,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":20,"ac_touch":13,"ac_flat_footed":20,"ac_mods":"+2 armor, +3 deflection, -1 Dex, +5 natural, +1 size","hp":64,"hd":"10d8+20","hd_value":10,"fort":9,"ref":4,"will":11,"speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"+1 spear +7 (1d6-1/x3), bite +1 (1d3-2)","ranged":"+1 spear +9 (1d6-1/19-20/x3) or magic stone +9 (1d6-1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"6/day, DC 16, 4d6"},{"type":"wooden fist","details":"+3, 8 rounds/day"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"touch of evil","details":"3 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":7,"spellsprepared_concentration":12,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"giant vermin"},{"spell":"summon monster IV"},{"spell":"unholy blight","type":"domain"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"bestow curse"},{"spell":"magic circle against good","type":"domain"},{"spell":"summon monster III"},{"spell":"water walk"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"barkskin","type":"domain"},{"spell":"bear's endurance"},{"spell":"hold person"},{"spell":"sound burst"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"bane"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"entangle","type":"domain"},{"spell":"magic stone"},{"spell":"obscuring mist"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"guidance"},{"spell":"mending"},{"spell":"virtue"}]}],"spelldomains":"Evil, Plant","strength":7,"dexterity":9,"constitution":12,"intelligence":15,"wisdom":20,"charisma":16,"baseatk":7,"cmb":4,"cmd":16,"feats":[{"feat":"Great Fortitude"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Selective Channeling"},{"feat":"Throw Anything","type":"bonus"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":10},{"skill":"Craft (alchemy)","value":8},{"skill":"Diplomacy","value":10},{"skill":"Heal","value":15},{"skill":"Knowledge (history)","value":7},{"skill":"Knowledge (planes)","value":12},{"skill":"Knowledge (religion)","value":12},{"skill":"Perception","value":6},{"skill":"Sense Motive","value":15},{"skill":"Spellcraft","value":10},{"skill":"Stealth","value":8},{"skill":"Survival","value":10}],"languages":["Common","Abyssal","Azlanti","Polyglot"],"sq":["bramble armor (1d6+3, 7 rounds/day)"],"gear":"+1 spear, bracers of armor +2, stone salve (1 ounce), wooden holy symbol of Angazhan, spell component pouch, 8 gp, potion of cure light wounds, potion of cure serious wounds, wand of silence (11 charges)","before_combat":"Akkituk casts barkskin, bear's endurance, and shield of faith before combat (already included in her stat block).","during_combat":"Akkituk doesn't try to engage in melee against the PCs; she lets her minions do that while she casts water walk and makes a fighting retreat to area D4. She casts her spells as she goes, pausing to summon monsters whenever she feels she can safely do so without one of the PCs catching up to her. If she reaches the statue of the ape demon, she uses her stone salve to waken it.","morale":"Akkituk is sure of her rewards from Angazhan if she dies fighting hairless infidels-she fights to the death as a result.","source":"AP 39, World Guide: The Inner Sea 308"},{"name":"Grugonoth","cr":10,"xp":9600,"race":"dire ape","gender":"Male","age_category":"Adult","alignment":"CE","size":"Huge","type":"outsider","sub_types":["native"],"templates_applied":"half-fiend advanced","init":4,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":24,"ac_touch":12,"ac_flat_footed":20,"ac_mods":"+4 armor, +4 Dex, +8 natural, -2 size","hp":126,"hd":"12d8+72","hd_value":12,"fort":14,"ref":12,"will":8,"dr":"10/magic","immunities":["poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":21,"speed":[{"type":"climb","speed":30},{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"bite +16 (2d6+9), 2 claws +16 (1d8+9)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+13"},{"type":"smite good","details":"1/day"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"contagion"},{"spell":"desecrate"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"poison"}]}],"strength":29,"dexterity":18,"constitution":22,"intelligence":6,"wisdom":14,"charisma":11,"baseatk":9,"cmb":20,"cmd":34,"feats":[{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Climb","value":21},{"skill":"Fly","value":19},{"skill":"Perception","value":23},{"skill":"Stealth","value":10}],"languages":["Abyssal"],"gear":"bracers of armor +4","during_combat":"If restored to life (likely via a dose of stone salve, perhaps along with a curse), Grugonoth roars and thrashes in delight and frustration for a round before immediately attacking all nearby targets-charau-ka and PCs alike. He begins battle with a blasphemy spell, but then relies on his melee attacks to destroy foes, resorting to spell-like abilities only against foes that seem resistant to physical damage.","morale":"Grugonoth's driving desire is to first seek out the Radiant Muse and slay her. His next plan is to reclaim his old rule over Saventh-Yhi. He won't risk his life against the PCs if that means putting these plans at risk, and flees any combat if reduced to fewer than 40 hit points by flying up into the sky and seeking out an abandoned ruin elsewhere in the city where he can heal and plot his next move.","source":"AP 39, Pathfinder RPG Bestiary 17, 171"},{"name":"Kech","cr":3,"xp":800,"race":"Kech","age_category":"Adult","alignment":"NE","size":"Medium","type":"monstrous humanoid","init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +3 natural","hp":26,"hd":"4d10+4","hd_value":4,"fort":2,"ref":6,"will":5,"speed":[{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"bite +5 (1d6+1), 2 claws +5 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d4+1"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"}]}],"strength":13,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":12,"charisma":11,"baseatk":4,"cmb":5,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Mobility"}],"skills":[{"skill":"Acrobatics","value":6,"special":"+4 jump"},{"skill":"Climb","value":16},{"skill":"Perception","value":10},{"skill":"Stealth","value":13,"special":"+6 in forested areas"}],"languages":["Kech"],"during_combat":"The keches attempt to wait until a PC is within 5 ft. before attacking, hoping to get a rend attack on the first round of combat. Unlike charau-ka, the keches are disturbingly silent when they fight.","morale":"A kech reduced to fewer than 9 hit points attempts to flee into the jungle.","source":"AP 39, Tome of Horrors Revised 247"},{"name":"Giant Mwangi Night Bat","cr":8,"xp":4800,"race":"dire bat","age_category":"Adult","alignment":"N","size":"Gargantuan","type":"animal","templates_applied":"advanced","init":3,"senses":["blindsense 40 ft."],"ac":19,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+3 Dex, +10 natural, -4 size","hp":114,"hd":"12d8+60","hd_value":12,"fort":13,"ref":11,"will":8,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":20}],"melee":"bite +16 (2d8+11/19-20), 2 wings +11 (1d8+5)","space":"20 ft.","reach":"15 ft.","strength":33,"dexterity":17,"constitution":21,"intelligence":2,"wisdom":14,"charisma":6,"baseatk":9,"cmb":24,"cmd":37,"feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Snatch"},{"feat":"Stealthy"}],"skills":[{"skill":"Escape Artist","value":5},{"skill":"Fly","value":9},{"skill":"Perception","value":10,"special":"+4 when using blindsense"},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":0}],"during_combat":"The giant bat uses Flyby Attack and Snatch to grab a single foe and then swoop up to the top of the ziggurat to kill him, repeating this tactic as necessary until all foes are dead.","morale":"The giant bat fights to the death.","source":"AP 39, Pathfinder RPG Bestiary 30"},{"name":"Ugimmo","cr":8,"xp":4800,"race":"boggard","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":7}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["boggard"],"init":5,"senses":["darkvision 60 ft.","low-light vision"],"ac":21,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+6 armor, +1 Dex, +1 dodge, +3 natural","hp":93,"hd":"10d8+49","hd_value":10,"fort":8,"ref":5,"will":8,"defensive_abilities":["armor of bones +6 (7 hours/day)"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"mwk morningstar +11 (1d8+2), tongue +4 touch (sticky tongue)","ranged":"savage sting +9 (1d2+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death's touch","details":"5/day, 1d6+3"},{"type":"soul siphon","details":"1/day, 2 minutes, +7 hit points"},{"type":"terrifying croak","details":"DC 16"}],"spellsknown_caster_level":7,"spellsknown_concentration":10,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"animate dead"},{"spell":"contagion"},{"spell":"inflict serious wounds"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"false life"},{"spell":"hold person"},{"spell":"inflict moderate wounds"},{"spell":"levitate"},{"spell":"minor image"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"bane"},{"spell":"cause fear"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"inflict light wounds"},{"spell":"obscuring mist"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"ghost sound"},{"spell":"guidance"},{"spell":"mage hand"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"spark"}]}],"mystery":"bones","strength":14,"dexterity":13,"constitution":14,"intelligence":10,"wisdom":13,"charisma":16,"baseatk":7,"cmb":9,"cmd":21,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Toughness"},{"feat":"Weapon Focus (morningstar)"}],"skills":[{"skill":"Acrobatics","value":2,"special":"+12 when jumping"},{"skill":"Bluff","value":11},{"skill":"Heal","value":6},{"skill":"Intimidate","value":11},{"skill":"Knowledge (history)","value":6},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":5},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":10,"special":"+8 in swamps"},{"skill":"Survival","value":6},{"skill":"Swim","value":10}],"languages":["Boggard"],"sq":["hold breath","oracle's curse (haunted)","revelations","swamp stride"],"gear":"savage sting (+1 seeking blowgun) with 10 darts, masterwork morningstar, cloak of resistance +1, hand of the mage, headband of alluring charisma +2, robe of bones, spell component pouch, onyx gems worth 750 gp, potion of cure light wounds","before_combat":"Ugimmo casts false life and activates his armor of bones revelation.","during_combat":"Ugimmo lets his zombies move to engage enemies while he supports their attacks with his own spells. He casts animate dead on any fallen PCs if the opportunity presents itself.","morale":"Ugimmo fights until reduced to fewer than 30 hit points, at which point he attempts to flee into the lake and then swim all the way to area N in hopes of soon contacting the \"spirit of the swamp\" to gain aid in crushing the PCs.","source":"AP 39, Pathfinder RPG Bestiary 37, Advanced Player's Guide 42"},{"name":"Amphisbaena","cr":7,"xp":3200,"race":"amphisbaena","age_category":"Adult","alignment":"N","size":"Huge","type":"magical beast","templates_applied":"advanced","init":2,"senses":["all-around vision","darkvision 60 ft.","low-light  vision","scent"],"ac":21,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+2 Dex, +11 natural, -2 size","hp":85,"hd":"9d10+36","hd_value":9,"fort":9,"ref":10,"will":4,"defensive_abilities":["split"],"immunities":["petrification"],"resists":["cold 10"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":20},{"type":"swim","speed":20}],"melee":"2 bite +14 (2d6+6 plus poison)","space":"15 ft.","reach":"10 ft.","strength":22,"dexterity":14,"constitution":17,"intelligence":2,"wisdom":13,"charisma":4,"baseatk":9,"cmb":17,"cmd":29,"cmd_special":"can't be tripped","feats":[{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":14,"special":"-4 jump"},{"skill":"Climb","value":14},{"skill":"Perception","value":12},{"skill":"Stealth","value":8},{"skill":"Swim","value":14}],"special_abilities":[{"type":"All-Around Vision","kind":"Ex","details":"An amphisbaena sees in all directions at once. It cannot be flanked."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 17; frequency 1/round for 4 rounds; effect 1d3 Con; cure 1 save."},{"type":"Split","kind":"Ex","details":"An amphisbaena functions normally even if cut in half. If dealt a critical hit with a slashing weapon, the creature is cut in half but continues to function as two separate creatures, each with half the original amphisbaena's current hit points (rounded down). Once split, an amphisbaena cannot be split again. If left alone for 1 minute, the split amphisbaena can rejoin its two halves and become a single whole creature again (add the two creatures' hit points together). If one of the split creatures is slain, the amphisbaena can regrow the lost portion over the course of a few weeks."}],"during_combat":"The amphisbaena ignores anyone who comes even to the very edge of this vast pool, but swiftly moves to attack anything that enters the water-it prefers larger targets over smaller ones, given the option.","morale":"The amphisbaena fights to the death.","source":"AP 39, Tome of Horrors Revised 12"},{"name":"The Nightmare Dancer","cr":8,"xp":4800,"race":"dream spider","age_category":"Adult","alignment":"N","size":"Huge","type":"vermin","templates_applied":"advanced","init":3,"senses":["darkvision 60 ft.","tremorsense 60 ft."],"ac":21,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+3 Dex, +10 natural, -2 size","hp":105,"hd":"10d8+60","hd_value":10,"fort":13,"ref":6,"will":4,"immunities":["mind-affecting effects"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":30}],"melee":"bite +15 (3d6+15 plus poison)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"dream web","details":"+8 ranged, DC 21, 10 hp"}],"strength":30,"dexterity":17,"constitution":22,"wisdom":12,"charisma":11,"baseatk":7,"cmb":19,"cmd":32,"cmd_special":"44 vs. trip","feats":[{"feat":"Improved Natural Attack (bite)","type":"bonus"}],"skills":[{"skill":"Climb","value":18},{"skill":"Perception","value":5},{"skill":"Stealth","value":-5,"special":"+4 in webs"}],"special_abilities":[{"type":"Dream Web","kind":"Ex","details":"A dream spider has the web ability (Pathfinder RPG Bestiary 305) but its webs carry an iridescent hue, making them easy to notice (Perception DC 15). Any animal, humanoid, or monstrous humanoid that comes in contact with these webs experiences strange hallucinations, taking 1d6 points of Wisdom damage per round of contact. A DC 21 Fortitude save negates this damage. If the webs of a dream spider are burned, they create a spread of poisonous gas in a 10-foot radius. This gas deals 1d8 points of Wisdom damage to all creatures in the area (not just to those susceptible to contact with webs as listed above). A DC 21 Fortitude save halves this damage. The cloud of colorful vapor remains for only a single round before dissipating harmlessly. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 21; frequency 1/round for 4 rounds; initial effect 1d3 Wis; secondary effect 1d3 Wis and paralysis for 2d6 hours; cure 1 save."}],"during_combat":"The Nightmare Dancer's tremorsense ability allows it to sense if anything brushes against its webs in the entire plaza, effectively extending the length of this ability for those purposes. If it notices any intruders, it immediately clambers out of its pit to attack-it ignores vegepygmies completely unless they attack it, in which case it fights them as well. The giant spider pursues foes anywhere in this district, but not beyond its borders.","morale":"The Nightmare Dancer fights to the death.","source":"AP 39, Pathfinder #7 82"},{"name":"Kliboolya","cr":6,"xp":2400,"race":"vegepygmy","age_category":"Adult","classes":[{"class":"rogue","level":6}],"alignment":"N","size":"Small","type":"plant","templates_applied":"advanced","init":10,"senses":["darkvision 60 ft.","low-light vision"],"ac":23,"ac_touch":17,"ac_flat_footed":17,"ac_mods":"+1 armor, +6 Dex, +5 natural, +1 size","hp":72,"hd":"7d8+41","hd_value":7,"fort":9,"ref":11,"will":4,"defensive_abilities":["evasion","trap sense +2","uncanny dodge"],"dr":"5/slashing or bludgeoning","immunities":["electricity","plant traits"],"speed":[{"type":"land","speed":35}],"melee":"+1 spear +10 (1d6+7/x3) and claw +7 (1d4+2 plus russet mold) or 2 claws +12 (1d4+4 plus russet mold)","ranged":"mwk composite shortbow +12 (1d4+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+3d6"}],"strength":18,"dexterity":22,"constitution":20,"intelligence":14,"wisdom":15,"charisma":13,"baseatk":4,"cmb":7,"cmd":23,"feats":[{"feat":"Combat Reflexes"},{"feat":"Fleet"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Appraise","value":7},{"skill":"Climb","value":14},{"skill":"Escape Artist","value":16},{"skill":"Intimidate","value":11},{"skill":"Knowledge (local)","value":12},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Sleight of Hand","value":16},{"skill":"Stealth","value":23,"special":"+8 in vegetation"}],"languages":["Common","Polyglot","Undercommon","Vegepygmy (cannot speak)"],"sq":["rogue talents (bleeding attack +3, finesse rogue, surprise attack)","trapfinding +3"],"special_abilities":[{"type":"Russet Mold","kind":"Ex","details":"Kliboolya infects any creature it hits with its natural weapons with russet mold spores. The victim must make a DC 15 Fortitude save or the spores take root, inflicting 2 points of Constitution damage per round. A new Fortitude save can be attempted each round to halt the growth."}],"gear":"broken moldy leather armor, +1 spear, masterwork composite shortbow with 20 arrows, brooch of shielding, 13 gp, potion of cure light wounds, potion of invisibility","during_combat":"Kliboolya moves to flank foes with its fellow vegepygmies, using multiple claws for the first few rounds so as to spread more spores around, and then switching to use its dagger in one hand once it has infested at least two enemies with spores.","morale":"Kliboolya fights to the death, but doesn't pursue foes off its ziggurat.","source":"AP 39, Pathfinder RPG Bestiary 273, 294"},{"name":"Egzimora","cr":9,"xp":6400,"race":"green hag","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":7}],"alignment":"CE","size":"Medium","type":"monstrous humanoid","init":7,"senses":["darkvision 90 ft."],"ac":24,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+3 Dex, +11 natural","hp":112,"hd":"9d10+7d6+39","hd_value":16,"fort":9,"ref":11,"will":13,"save_mods":"+2 vs. poison and sleep","sr":16,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"2 claws +16 (1d4+4 plus weakness [DC 18])","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"},{"spell":"tongues"},{"spell":"water breathing"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"dancing lights"},{"spell":"ghost sound"},{"spell":"invisibility"},{"spell":"pyrotechnics"},{"spell":"tree shape"}]},{"frequency":"7/day","spells":[{"spell":"tanglevine","details":"+11"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":7,"spellsknown_concentration":11,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"speak with plants"},{"spell":"stinking cloud"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"barkskin"},{"spell":"scorching ray"},{"spell":"summon swarm"},{"spell":"touch of idiocy"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"charm person"},{"spell":"endure elements"},{"spell":"entangle"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"},{"spell":"shocking grasp"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"bloodline":"verdant","strength":18,"dexterity":16,"constitution":14,"intelligence":15,"wisdom":15,"charisma":18,"baseatk":12,"cmb":16,"cmd":29,"feats":[{"feat":"Acrobatic Steps"},{"feat":"Alertness"},{"feat":"Blind- Fight"},{"feat":"Combat Casting"},{"feat":"Deceitful"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Nimble Moves"},{"feat":"Spell Focus (enchantment)"}],"skills":[{"skill":"Bluff","value":26},{"skill":"Disguise","value":22},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":21},{"skill":"Swim","value":18}],"languages":["Common","Aklo","Giant"],"sq":["bloodline arcana","mimicry","photosynthesis"],"special_abilities":[{"type":"Photosynthesis","kind":"Ex","details":"Egzimora can feed upon nature's raw essence. Her need to eat and sleep is reduced as if she were wearing a ring of sustenance, and she gains a +2 racial bonus on saving throws made against poison and sleep effects."},{"type":"Tanglevine","kind":"Sp","details":"As a standard action, Egzimora can create a 15-foot-long, animated vine that springs from her hand. This vine lasts for 1 round and can be used to make a single disarm, steal, or trip combat maneuver, using her sorcerer level plus her Charisma modifier in place of her normal CMB. Verdant Bloodline The verdant bloodline may be found on page 141 of the Pathfinder RPG Advanced Player's Guide."}],"gear":"elixir of love, 45 gp, potions of cure moderate wounds (2), potion of resist energy (fire), wand of bestow curse (9 charges), wand of lightning bolt (23 charges)","before_combat":"Egzimora casts barkskin before combat.","during_combat":"Egzimora reverts to her true form so she can use her claws in combat. If reduced to fewer than 80 hit points, she attempts to escape by becoming invisible, then takes up a position where she can utilize her spells at range without facing foes in melee.","morale":"If reduced to fewer than 25 hit points, she flees entirely, only to seek out the PCs' camp at a later date to try to lure one of them or their allies away to a hideous fate.","source":"AP 39, Pathfinder RPG Bestiary 167"},{"name":"Tribal Hunter","cr":3,"xp":800,"race":"human","age_category":"Adult","classes":[{"class":"ranger","level":2,"archetype":"guide"},{"class":"rogue","level":2,"archetype":"sniper"}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":8,"ac":17,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 armor, +4 Dex","hp":30,"hd":"2d10+2d8+10","hd_value":4,"fort":4,"ref":10,"will":1,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":30}],"melee":"mwk battleaxe +6 (1d8+2/x3), kukri +5 (1d4+2/18-20)","ranged":"mwk composite longbow +9 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"accuracy"},{"type":"ranger's focus"},{"type":"sneak attack","details":"+1d6"}],"strength":14,"dexterity":18,"constitution":12,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":3,"cmb":5,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Toughness"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":9},{"skill":"Escape Artist","value":11},{"skill":"Heal","value":6},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":8},{"skill":"Stealth","value":11},{"skill":"Survival","value":8}],"languages":["Polyglot"],"sq":["rogue talents (snap shot)"],"special_abilities":[{"type":"Accuracy","kind":"Ex","details":"A sniper halves all range increment penalties when making ranged attacks with a bow or crossbow. This ability replaces trapfinding."},{"type":"Ranger's Focus","kind":"Ex","details":"Once per day, a guide can focus on a single enemy within line of sight as a swift action. That creature remains the ranger's focus until it is reduced to 0 or fewer hit points or surrenders, or until the ranger designates a new focus, whichever occurs first. The ranger gains a +2 bonus on attack and damage rolls against the target of his focus. This ability replaces favored enemy."},{"type":"Snap Shot","kind":"Ex","details":"A rogue with this talent may treat her initiative roll as a 20 for a surprise round, regardless of her initiative, but she may only take an attack action with a ranged weapon. Her normal initiative roll is used in subsequent rounds. If two or more rogues possess this talent, their initiative determines the order in which they act, but they all go before any other creature. If a rogue is prevented from acting in the surprise round, this talent has no effect."}],"gear":"masterwork studded leather, masterwork battleaxe, kukri, masterwork composite longbow (+2 Str) with 10 arrows, flint and steel, 6 gp, +1 arrows (10), elixir of hiding, potion of cure moderate wounds, potion of darkvision, smokestick, thunderstone","during_combat":"The tribal hunters hold back in combat, using their longbows to pick off enemies if possible. Once the enemy engages them in melee, they abandon their bows and work in pairs to flank foes so they can make sneak attacks with their axes.","morale":"These tribal hunters fight to the death as long as the Radiant Muse lives-if they know she is dead, they flee combat once reduced to 15 or fewer hit points.","source":"AP 39, Advanced Player's Guide 125, 134"},{"name":"Osond","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"druid","level":9}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":23,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+6 armor, +1 deflection, +2 Dex, +4 natural","hp":76,"hd":"9d8+36","hd_value":9,"fort":8,"ref":7,"will":10,"save_mods":"+4 vs. fey and plant-targeted effects","defensive_abilities":["resist nature's lure"],"immunities":["poison"],"speed":[{"type":"land","speed":20}],"melee":"+1 scimitar +7 (1d6+1/18-20)","ranged":"sling +8 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"lightning lord","details":"9 bolts/day"},{"type":"storm burst","details":"1d6+4 nonlethal damage, 7/day"},{"type":"wild shape 9 hours/day"}],"spellsprepared_caster_level":9,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"call lightning storm"},{"spell":"ice storm","type":"domain"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"cure serious wounds"},{"spell":"flame strike"},{"spell":"freedom of movement"},{"spell":"sleet storm","type":"domain"}]},{"spell_level":3,"spell_slots":2,"spells":[{"spell":"call lightning","type":"domain"},{"spell":"remove disease"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"barkskin"},{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"chill metal"},{"spell":"flame blade"},{"spell":"fog cloud","type":"domain"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"cure light wounds"},{"spell":"entangle"},{"spell":"goodberry"},{"spell":"magic stone"},{"spell":"obscuring mist","type":"domain"},{"spell":"produce flame"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"stabilize"}]}],"spelldomains":"Weather","strength":10,"dexterity":14,"constitution":14,"intelligence":12,"wisdom":18,"charisma":8,"baseatk":6,"cmb":6,"cmd":19,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Lightning Reflexes"},{"feat":"Natural Spell"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":12},{"skill":"Heal","value":16},{"skill":"Knowledge (geography)","value":8},{"skill":"Knowledge (nature)","value":15},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":11},{"skill":"Survival","value":18}],"languages":["Common","Celestial","Druidic","Polyglot"],"sq":["nature bond (Weather domain)","nature sense","trackless step","wild empathy +8","woodland stride"],"gear":"+2 hide armor, +1 scimitar, sling with 10 bullets, regalia of the Radiant Muse (feathered cloak that functions as wings of flying), ring of protection +1, spell component pouch","before_combat":"Osond casts barkskin before entering combat.","during_combat":"Osond lets his hunters engage foes while he hangs back to cast defensive spells like bear's endurance, bull's strength, and protection from energy. He interrupts these spells to cast supporting spells into a battle to aid his allies or to provide additional summoned monsters as allies. Once half his hunters have fallen, Osond steps in to join in melee, using wild shape to assume the form of a Medium air elemental to fight.","morale":"Osond fights to the death.","source":"AP 39"},{"name":"The Radiant Muse","cr":13,"xp":9600,"race":"lillend","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":6}],"alignment":"CN","size":"Large","type":"outsider","sub_types":["azata","chaotic","extraplanar"],"init":10,"senses":["darkvision 60 ft.","low-light vision"],"ac":29,"ac_touch":16,"ac_flat_footed":23,"ac_mods":"+5 armor, +1 deflection, +6 Dex, +8 natural, -1 size","hp":156,"hd":"7d10+6d8+91","hd_value":13,"fort":9,"ref":16,"will":14,"save_mods":"+4 vs. bardic performance,  language-dependent, and sonic","immunities":["electricity","petrification","poison"],"resists":["cold 10","fire 10"],"speed":[{"type":"fly","speed":70,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"mwk longsword +15 (2d6+6/19-20), tail slap +9 (2d6+2)","ranged":"+2 composite longbow +19 (2d6+6/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bardic performance 34 rounds/day","details":"countersong, dirge of doom, distraction, fascinate, inspire competence +4, inspire courage +3, inspire greatness, soothing performance, suggestion"},{"type":"constrict","details":"2d6+4"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"charm person"},{"spell":"speak with animals"},{"spell":"speak with plants"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"hallucinatory terrain"},{"spell":"knock"},{"spell":"light"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":13,"spellsknown_concentration":19,"spellsknown":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"mass cure light wounds"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"dimension door"},{"spell":"dominate person"},{"spell":"greater invisibility"},{"spell":"rainbow pattern"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"charm monster"},{"spell":"crushing despair"},{"spell":"cure serious wounds"},{"spell":"good hope"},{"spell":"lesser geas"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blindness/deafness"},{"spell":"blur"},{"spell":"hold person"},{"spell":"suggestion"},{"spell":"whispering wind"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds"},{"spell":"hideous laughter"},{"spell":"hypnotism"},{"spell":"lesser confusion"},{"spell":"remove fear"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":18,"dexterity":22,"constitution":23,"intelligence":16,"wisdom":18,"charisma":23,"baseatk":11,"cmb":16,"cmd":33,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Casting"},{"feat":"Improved Initiative"},{"feat":"Improved Precise Shot"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Toughness"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Craft (sculpture)","value":19},{"skill":"Intimidate","value":22},{"skill":"Knowledge (arcana)","value":15},{"skill":"Knowledge (history)","value":15},{"skill":"Knowledge (nature)","value":15},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":14},{"skill":"Perform (dance)","value":22},{"skill":"Perform (oratory)","value":22},{"skill":"Perform (string)","value":24},{"skill":"Sense Motive","value":20},{"skill":"Survival","value":18},{"skill":"Use Magic Device","value":20}],"languages":["Common","Celestial","Draconic","Infernal; truespeech"],"sq":["bardic knowledge +3","lore master 1/day","versatile performance (dance: Acrobatics, Fly; string: Bluff, Diplomacy)"],"gear":"+1 glamered chain shirt, green crystal +1 flaming composite longbow (+4 Str) with 9 arrows, masterwork longsword, belt of mighty constitution +2, ring of protection +1, masterwork harp, +1 flaming arrows (3), +1 frost arrows (3), +1 merciful arrows (2), +1 monstrous humanoid bane arrows (3), scrolls of comprehend languages (3)","during_combat":"The Radiant Muse's first act in combat is to cast greater invisibility and inspire courage with her bardic performance. If she has allies nearby, she lets them fight while bolstering them with her spells or hindering the PCs with the same. On her own, she stays in motion for the first several rounds of combat, using spells while flying from rooftop to rooftop. Once she's got the party disorganized with her magic, she settles down on a rooftop and focuses her longbow attacks on a single foe.","morale":"The Radiant Muse fights to the death, but will accept any request of an enemy to surrender.","source":"AP 39, Pathfinder RPG Bestiary 26"},{"name":"Boggard Subchief","cr":4,"xp":1200,"race":"Boggard","age_category":"Adult","classes":[{"class":"barbarian","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["boggard"],"init":1,"senses":["darkvision 60 ft.","low-light vision"],"ac":16,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+4 armor, +1 Dex, +3 natural, -2 rage","hp":53,"hd":"3d8+2d12+27","hd_value":5,"fort":11,"ref":2,"will":4,"defensive_abilities":["uncanny dodge"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"+1 greataxe +12 (1d12+10/x3), tongue +5 touch (sticky tongue)","ranged":"throwing axe +5 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"9 rounds/day"},{"type":"rage powers","details":"superstition +2"},{"type":"terrifying croak","details":"DC 12"}],"strength":23,"dexterity":13,"constitution":20,"intelligence":8,"wisdom":13,"charisma":8,"baseatk":4,"cmb":10,"cmd":19,"feats":[{"feat":"Dazzling Display"},{"feat":"Intimidating Prowess"},{"feat":"Weapon Focus (greataxe)"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+12 when jumping"},{"skill":"Intimidate","value":13},{"skill":"Perception","value":9},{"skill":"Survival","value":5},{"skill":"Swim","value":16}],"languages":["Boggard"],"sq":["fast movement","hold breath","swamp stride"],"gear":"masterwork hide armor, +1 greataxe, throwing axes (3), 141 gp, potion of cure light wounds","during_combat":"A boggard subchief rages at the start of combat and uses his terrifying croak (more to raise an alarm than in hopes of frightening the PCs), then enters combat in melee. The subchief only makes ranged attacks with throwing axes if it seems apparent that the boggard can't engage any foe in hand-to-hand combat.","morale":"A boggard subchief fights to the death.","base_statistics":"When not raging, a subchief's statistics are AC 18, touch 11, flat-footed 17; hp 43; Fort +9; Melee +1 greataxe +10 (1d12+7/x3), tongue +3 touch (sticky tongue); Ranged throwing axe +5 (1d6+4) Str 19, Con 16; CMB +8; Skills Intimidate +11, Swim +14","source":"AP 39, Pathfinder RPG Bestiary 37"},{"name":"Garluu","cr":9,"xp":6400,"race":"boggard","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":8}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["boggard"],"init":6,"senses":["darkvision 60 ft.","low-light vision"],"ac":23,"ac_touch":12,"ac_flat_footed":21,"ac_mods":"+7 armor, +2 Dex, +4 natural","hp":109,"hd":"3d8+8d10+52","hd_value":11,"fort":12,"ref":5,"will":6,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"+2 falchion +20 (2d4+12/15-20), tongue +10 touch (sticky tongue)","ranged":"mwk heavy crossbow +13 (1d10/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"terrifying croak","details":"DC 12"},{"type":"weapon training","details":"heavy blades +1"}],"strength":20,"dexterity":14,"constitution":16,"intelligence":8,"wisdom":13,"charisma":8,"baseatk":10,"cmb":15,"cmd":27,"feats":[{"feat":"Critical Focus"},{"feat":"Greater Weapon Focus (falchion)"},{"feat":"Improved Critical (falchion)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Armor"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (falchion)"},{"feat":"Weapon Specialization (falchion)"}],"skills":[{"skill":"Acrobatics","value":4,"special":"+12 when jumping"},{"skill":"Intimidate","value":7},{"skill":"Perception","value":5},{"skill":"Stealth","value":4,"special":"+8 in swamps"},{"skill":"Swim","value":12}],"languages":["Boggard"],"sq":["armor training 2","hold breath","swamp stride"],"gear":"+1 breastplate, +2 falchion, masterwork heavy crossbow with 20 bolts, potion of cure moderate wounds","during_combat":"Garluu only resorts to his crossbow against foes he can't reach in combat, as he much prefers to use his falchion. He also prefers to fight in swampy land where his ability to move through the difficult terrain gives him an advantage.","morale":"Garluu fights until reduced to fewer than 30 hit points, at which he drops his weapon and begs for mercy in a cowardly fashion-he'll even agree to an alliance with the PCs if they spare his life.","source":"AP 39, Pathfinder RPG Bestiary 37"},{"name":"Vrykolakas","cr":10,"xp":9600,"race":"Vrykolakas","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","init":8,"senses":["darkvision 60 ft."],"auras":["pestilent aura (5 ft., DC 21)"],"ac":23,"ac_touch":15,"ac_flat_footed":18,"ac_mods":"+4 Dex, +1 dodge, +8 natural","hp":115,"hd":"10d8+70","hd_value":10,"hp_mods":"fast healing 5","fort":9,"ref":9,"will":11,"defensive_abilities":["channel resistance +4"],"immunities":["undead traits"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"2 claws +13 (1d6+6 plus energy drain), bite +13 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"energy drain","details":"1 level, DC 21"},{"type":"rend","details":"2 claws, 1d6+9"}],"spell_like_abilities_caster_level":10,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"charm animal"},{"spell":"disguise self"},{"spell":"fear"}]}],"strength":22,"dexterity":19,"intelligence":7,"wisdom":18,"charisma":23,"baseatk":7,"cmb":13,"cmd":28,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Stealthy"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":14},{"skill":"Disguise","value":6},{"skill":"Perception","value":17},{"skill":"Stealth","value":21}],"languages":["Common"],"sq":["feral possession"],"special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any humanoid creature that is slain by a vrykolakas's natural attacks becomes a vrykolakas itself in 1d4 days if not blessed and properly buried. A blessing might entail either the spell bless or a more mundane consecration. A vrykolakas's spawn are free-willed and wild, typically remembering nothing of their moment of death and caring nothing for the vrykolakas that killed them. They don't possess any of the abilities they had in life."},{"type":"Feral Possession","kind":"Ex","details":"Upon being reduced to 0 hit points, a vrykolakas's spirit attempts to possess any animal within 100 feet. This ability is similar to the spell magic jar, but doesn't require a receptacle and has a duration equal to 1 hour for every Hit Die the vrykolakas possesses. The target must make a DC 21 Will save or be possessed. If the possession fails, the vrykolakas immediately dies. If the possession succeeds, the animal immediately retreats to the vrykolakas's grave, where it attempts to bury itself in the earth. If left uninterrupted for 1d4 days, the animal transforms into a new vrykolakas with all the same statistics as the original. If discovered and slain during this time, both the animal and the vrykolakas spirit are destroyed. The save DC is Charisma-based."},{"type":"Pestilent Aura","kind":"Su","details":"All creatures that come within 5 ft. of a vrykolakas must save to resist contracting bubonic plague. Any creature that successfully saves against a vrykolakas's pestilent aura cannot be affected by the aura of that same vrykolakas for 24 hours. The save DC is Charisma-based. Bubonic Plague: Aura-inhaled; save Fort DC 21; onset 1 day; frequency 1/day; effect 1d4 Str damage and 1 Cha damage and target is fatigued; cure 2 consecutive saves."}],"during_combat":"The vrykolakas attempts to charm any animal companions the PCs might have with them, then uses fear to try to scatter foes so it can focus its attacks on a single target (preferably a divine spellcaster).","morale":"If reduced to 0 hit points, the vrykolakas attempts to possess a nearby frog (use stats for a toad-Pathfinder RPG Bestiary 133). The frog has a Will save of +1; if it fails to resist the possession attempt, the creature tries to stealthily return to the vrykolakas's den to recover-when it awakens, it emerges from its grave and attempts to seek out the PCs for revenge.","source":"AP 39, Pathfinder #29 88"}];
